const SECTIONS = [
 {id:'music',title:'Music in our lives',subtitle:'Meaning, mood & music vocabulary',time:'3 min',color:'#ffe0b6'},
 {id:'reading',title:'Music connects us',subtitle:'The Golden Record & the reading',time:'4 min',color:'#cce7df'},
 {id:'technology',title:'Music & technology',subtitle:'Listening choices & future possibilities',time:'2 min',color:'#ded7f6'},
 {id:'focus',title:'Sound & recommendations',subtitle:'Choose a soundscape for a purpose',time:'3 min',color:'#f5d4dc'},
 {id:'language',title:'Language in context',subtitle:'Describe things, actions & past scenes',time:'3 min',color:'#cde2f4'},
 {id:'forest',title:'The Silent Forest',subtitle:'Cause, evidence & connection',time:'3 min',color:'#dce8bb'}
];
const QUESTIONS = [
 {id:1,section:'music',type:'mc',prompt:'A chorus keeps playing in your head long after the song ends. What is this called?',options:['A soundtrack','An earworm','A playlist','A genre'],answer:1,explanation:'An earworm is a tune that repeats in your mind. A soundtrack accompanies a film or other production; a playlist is a collection of tracks.'},
 {id:2,section:'music',type:'mc',prompt:'A producer speeds up a track without changing how high or low its notes sound. What changes?',options:['Its genre, but not its lyrics','Its pitch, but not its tempo','Its tempo, but not its pitch','Its melody, but not its beat'],answer:2,explanation:'Tempo is the speed of music. Pitch describes how high or low a note sounds. The beat is its regular pulse, and rhythm is the pattern of sounds.'},
 {id:3,section:'music',type:'mc',prompt:'The introduction says music can influence our circadian rhythm. What does this term refer to?',options:['Our daily cycle of sleeping and waking','The order of tracks on a playlist','How quickly we learn song lyrics','Our favourite musical genre'],answer:0,explanation:'Circadian rhythm is the body’s daily cycle, including sleeping and waking. It is different from musical rhythm.'},
 {id:4,section:'music',type:'short',prompt:'Name a track or genre and explain one effect it has on you. Use at least one of these words: beat, melody, rhythm, lyrics.',model:'Pop music’s steady beat makes me feel energetic when I walk to school.',checks:['I name a track or genre and explain a clear personal effect.','I use beat, melody, rhythm or lyrics with a suitable meaning.'],explanation:'Different reactions are valid. Link a feature of the music to your own response.'},
 {id:5,section:'reading',type:'mc',prompt:'Why was music included on Voyager’s Golden Record?',options:['To teach astronauts to perform concerts','To advertise popular musicians on Earth','To help the probe find its way home','To help possible intelligent life understand life and culture on Earth'],answer:3,explanation:'The record contains material representing Earth, including music, sounds and images. Its intended audience was possible intelligent life beyond Earth.'},
 {id:6,section:'reading',type:'mc',prompt:'Read this review summary: “In ancient Greece, music was connected with inspiration and many areas of life. People believed it could support healing, sport and work.” Which is the best paragraph topic?',options:['Music mattered in several areas of Greek society','All Greek music was written for athletes','Greek music was mainly about space travel','Greek teenagers avoided musical instruments'],answer:0,explanation:'A paragraph topic should cover the whole paragraph. Healing, sport and work are examples supporting the broader idea of music’s place in Greek society.'},
 {id:7,section:'reading',type:'mc',prompt:'According to the article, what helps explain why music and speech can both communicate emotion?',options:['They always use the same words','They only communicate when they are loud','Pitch and speed can express feelings in both','Everyone understands every song in the same way'],answer:2,explanation:'Changes in pitch and speed can communicate emotion in speech and music. This does not mean that every listener has an identical response.'},
 {id:8,section:'reading',type:'mc',prompt:'What did the study comparing the Mbenzele group and the Montreal group suggest?',options:['Only familiar music can affect people','Music can produce similar feelings across cultures','All cultures prefer the same musical genre','Music removes the need to learn languages'],answer:1,explanation:'The groups showed similar responses such as excitement or calmness. This supports the idea of a common musical language, without proving that all musical meanings are universal.'},
 {id:9,section:'reading',type:'short',prompt:'Why can recognising patterns help humans survive? Give one example in one sentence.',model:'Recognising that smoke may mean fire helps people predict danger and move to safety.',checks:['I connect recognising a pattern with predicting an outcome or danger.','I give a relevant example and show how it helps someone respond.'],explanation:'The article links pattern recognition with prediction and survival, then suggests that predictable musical patterns may help explain our enjoyment of music.'},
 {id:10,section:'technology',type:'mc',prompt:'Which example describes streaming music rather than playing a physical recording?',options:['Playing a vinyl record on a turntable','Putting a CD into a player','Watching musicians perform in person','Listening to tracks through an online music service'],answer:3,explanation:'Streaming delivers music through an online service. CDs and vinyl are physical recordings; a live concert is an in-person performance.'},
 {id:11,section:'technology',type:'short',prompt:'Choose virtual reality, hologram popstars or wireless earbuds. Predict one possible effect on listeners using may, might or could.',model:'Virtual reality could let listeners feel as if they are inside a concert while staying at home.',checks:['I give a plausible effect on listeners linked to the technology I choose.','I express a possibility using may, might or could.'],explanation:'Several predictions are possible. Explain what the technology might allow people to experience; no sales figures or trend language are needed.'},
 {id:12,section:'focus',type:'mc',prompt:'A gentle sound helps someone feel calm. Which adjective best describes its effect?',options:['Irritating','Soothing','Alarming','Confusing'],answer:1,explanation:'Soothing sounds have a calming effect. Irritating sounds annoy us, and alarming sounds make us worried or alert to danger.'},
 {id:13,section:'focus',type:'mc',prompt:'A student notices that song lyrics distract her during revision. What is the most sensible next step?',options:['Play the same songs more loudly','Choose music only because her friends like it','Try quiet instrumental music or silence and compare her focus','Assume all music affects every student identically'],answer:2,explanation:'Choose a soundscape for the task and the person. Testing alternatives gives evidence about what helps this student concentrate.'},
 {id:14,section:'focus',type:'short',prompt:'Recommend a soundscape for either an exercise class or a dentist’s waiting room. Give a reason or predicted outcome in the same sentence.',model:'I would recommend upbeat music for an exercise class because it may help people feel energetic.',checks:['I make a clear recommendation suited to the place I choose.','I justify it with a relevant reason or predicted effect.'],explanation:'A waiting room might suit calming sounds; exercise might suit energetic music. Other choices are valid if the reason fits the situation.'},
 {id:15,section:'language',type:'mc',prompt:'Choose the correct adjective + noun combination for the story: “Eva heard ___ from the leaves.”',options:['a gentle rustling','a gently rustling','a gentle rustlely','a gentleness rustling'],answer:0,explanation:'Gentle is an adjective describing the noun rustling. Gently is an adverb, usually used to describe an action.'},
 {id:16,section:'language',type:'mc',prompt:'Choose the forms that complete the sentence: “Music brought ___ to Eva, and she danced ___.”',options:['happy / happiness','happily / happy','happiness / happy','happiness / happily'],answer:3,explanation:'Happiness is an abstract noun naming an emotion. Happily is an adverb describing how she danced. Other abstract nouns include harmony, creativity and inspiration.'},
 {id:17,section:'language',type:'short',prompt:'Describe the forest before or after the animals returned. Write one sentence using there was/were + adjective + noun.',model:'There were cheerful birds in the forest after the animals returned.',checks:['I use there was with a singular/uncountable noun, or there were with a plural noun.','I place an adjective before a suitable noun in a meaningful forest description.'],explanation:'For example: There was a quiet river. / There were playful animals. Use a past scene rather than a technology trend.'},
 {id:18,section:'forest',type:'mc',prompt:'In The Silent Forest, why had the creatures left?',options:['Eva’s flute frightened them away','They could no longer find safe drinking water in the polluted river','Tom had moved all the animals to another town','The elders had stopped playing music'],answer:1,explanation:'All the animals needed water. Pollution and sediment affected the river, so the creatures went elsewhere to find good water.'},
 {id:19,section:'forest',type:'mc',prompt:'Why does Tom investigate the river before asking Eva to play her flute again?',options:['He wants to replace Eva’s flute with a louder one','He believes music can solve every problem immediately','He needs to identify and address the cause of the animals’ disappearance','He wants to teach the elders a new song'],answer:2,explanation:'Tom first follows evidence and identifies the shared water source. The upstream town agrees to move its rubbish dump and clear sediment before Eva calls the animals back.'},
 {id:20,section:'forest',type:'short',prompt:'How do Tom’s knowledge and Eva’s music help bring the animals back to the forest? Write one sentence.',model:'Tom’s knowledge helps the towns make the river safe again, and Eva’s music calls the animals back afterwards.',checks:['I explain that knowledge or investigation helps identify and solve the water problem.','I explain that Eva’s music calls the animals back after conditions improve.'],explanation:'The ending combines investigation, community action and musical connection. The flute does not clean the river by itself.'}
];
function answered(q,answers){return q.type==='mc'?Number.isInteger(answers[q.id])&&answers[q.id]>=0&&answers[q.id]<q.options.length:typeof answers[q.id]==='string'&&answers[q.id].trim().length>0;}
function resultsFor(section,answers,ratings){const qs=QUESTIONS.filter(q=>q.section===section);const mc=qs.filter(q=>q.type==='mc');const shorts=qs.filter(q=>q.type==='short');return {correct:mc.filter(q=>answered(q,answers)&&answers[q.id]===q.answer).length,total:mc.length,shorts:shorts.length,reviewed:shorts.filter(q=>[0,1,2].includes(ratings[q.id])).length,shortPoints:shorts.reduce((n,q)=>n+(ratings[q.id]??0),0)};}
if(typeof module!=='undefined')module.exports={SECTIONS,QUESTIONS,answered,resultsFor};
